var sliding = false;

function slideout() {
    if (sliding) return;
    sliding = true;
    var body = document.body;
    body.style.top = "-100vh";
    body.style.transform = "translateY(-100vh)";
    setTimeout(function () {
        window.location.href = "/#about";
    }, 700);
}

// Reset state on back/forward cache navigation
window.addEventListener("pageshow", function () {
    sliding = false;
    document.body.style.top = "0px";
    document.body.style.transform = "none";
});

// Scroll down using mouse wheel
window.addEventListener("wheel", function (e) {
    if (e.deltaY > 0) {
        slideout();
    }
}, { passive: true });

// Scroll down using touch swipe
var touchStartY = 0;
window.addEventListener("touchstart", function (e) {
    if (e.touches && e.touches.length > 0) {
        touchStartY = e.touches[0].clientY;
    }
}, { passive: true });

window.addEventListener("touchmove", function (e) {
    if (e.touches && e.touches.length > 0) {
        var touchCurrentY = e.touches[0].clientY;
        if (touchStartY - touchCurrentY > 30) {
            slideout();
        }
    }
}, { passive: true });

// Scroll down using native scrollbar/overflow
window.addEventListener("scroll", function () {
    if (window.scrollY > 5) {
        slideout();
    }
}, { passive: true });

// Keyboard navigation (ArrowDown, PageDown, Space)
window.addEventListener("keydown", function (e) {
    if (e.key === "ArrowDown" || e.key === "PageDown" || (e.key === " " && !e.target.matches("input, textarea, button"))) {
        slideout();
    }
});